// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address ownerCaller, address providedMigrator) internal {
        ownerCaller = c.owner();
        try c.setMigrator(providedMigrator) {} catch { return; }
        assertTrue(c.migrator() == providedMigrator);
    }

    function testFuzz_run(address ownerCaller, address providedMigrator) public {
        vm.assume(uint160(providedMigrator) > 255 && providedMigrator != address(this) && providedMigrator != address(c) && providedMigrator != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && providedMigrator != 0x000000000000000000636F6e736F6c652e6c6f67 && providedMigrator != 0x4e59b44847b379578588920cA78FbF26c0B4956C && providedMigrator != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(ownerCaller, providedMigrator);
    }

    receive() external payable {}
}
